from oct11_seo_bodies._html import assemble, related


def body() -> str:
    return assemble(
        intro='Running and jogging attract people with Crohn\'s disease and ulcerative colitis who want cardio fitness, yet urgency, fatigue, and joint pain complicate route planning. This guide covers flare versus remission pacing, hydration, and links to <a href="/blog/yoga-for-ibd-crohns-colitis">yoga</a>, <a href="/blog/walking-for-ibd-crohns-colitis">walking</a>, <a href="/blog/strength-training-gym-ibd">strength training</a>, and <a href="/blog/exercise-during-ibd-flare">exercise during flares</a>. Education only.',
        sections=[('Why running tempts IBD patients', ['Running offers efficient cardio when time is tight and can boost mood when inflammation is quiet.', 'It also jostles the gut and raises urgency fears on routes without bathrooms.', 'A planned run walk program beats heroic sprints followed by crash naps.', 'Fitness goals should serve health, not punish flares.']), ('Remission baseline building', ['Start with run walk intervals on flat paths with known restrooms every mile or less.', 'Increase weekly mileage gently; many IBD runners cap increases below classic ten percent rules.', 'Rest days are training days too when calprotectin recently normalized.', 'Track morning heart rate or sleep if overtraining signs appear.']), ('Flare week downgrades', ['Swap outdoor runs for indoor walking, gentle yoga, or rest when calprotectin is high or stools turn nocturnal.', 'See exercise during flare article for red flags that stop all impact activity.', 'Maintaining zero movement sometimes worsens stiffness; choose lowest impact option approved by your team.', 'Return dates after flares should be tentative, not contractual.']), ('Bathroom mapping and gear', ['Scout coffee shops, gyms, and park restrooms along loops.', 'Carry a small kit: wipes, spare liner, zip bag, phone with offline maps.', 'Waist belts should not squeeze stoma appliances; adjust brands until bounce feels safe.', 'Tell one friend your loop path when running alone.']), ('Hydration and electrolytes on runs', ['Diarrhea plus sweat stacks fluid losses; sip early instead of chugging at the finish.', 'Ask clinicians before concentrated electrolyte packets if sugars trigger stools.', 'Practice drink timing on short loops before race day.', 'Weigh yourself before and after hot runs to estimate sweat loss.']), ('Heat, cold, and season shifts', ['Summer dawn runs reduce heat urgency for some people.', 'Winter layers help joints; warm up indoors before icy paths.', 'Allergy seasons may affect breathing; distinguish asthma from deconditioning.', 'Treadmills near home bathrooms reduce anxiety for beginners.']), ('Anemia and low hemoglobin', ['Low hemoglobin makes target paces impossible; treat iron and inflammation before chasing personal records.', 'Symptoms include breathlessness on stairs separate from running.', 'Repeat labs after iron trials per hematology advice.', 'Walk run intervals remain valid training while rebuilding stores.']), ('Joint disease and spondyloarthritis', ['Axial joint pain may prefer lower impact days when sacroiliac joints ache.', 'Physical therapy exercises complement running when cleared.', 'NSAIDs for joint pain often clash with IBD; ask before using them to run.', 'Shoe rotation and surface choice matter on inflamed days.']), ('Ostomy and J pouch runners', ['Support belts and appliance emptying before runs reduce worry.', 'Discuss bouncing impact with surgery teams after recent operations.', 'Hydration needs rise with high output ostomies.', 'Test adhesives in humidity before signing up for humid races.']), ('Medication timing and infusion weeks', ['Some feel best day after infusion; others feel wiped.', 'Log personal patterns a month before judging plans failed.', 'Steroid tapers can temporarily inflate capacity then crash during taper.', 'Anti diarrhea medicines around runs require clinician approval; never self medicate to force mileage.']), ('Race events versus casual jogs', ['Marathons are possible for some athletes with meticulous planning; many choose shorter events.', 'Corral bathroom lines stress urgency; plan conservative start times.', 'Packet pickup days disrupt routine; sleep and hydration still matter.', 'DNS a race without shame if a flare arrives race week.']), ('Strength cross training', ['Strong glutes and core stabilize running form when fatigue hits.', 'Link with strength training guide for twice weekly sessions.', 'Heavy squats during active flares may wait; bodyweight work might stay.', 'Balance run days with strength days to protect joints.']), ('Pelvic floor and urgency fear', ['Fear of incontinence stops some runners before muscles fail.', 'Pelvic floor physical therapy can help beyond willpower alone.', 'Gradual exposure runs near bathrooms rebuild confidence.', 'Dark clothing choices are personal coping tools, not medical requirements.']), ('When to stop and message clinic', ['Pause for new fever, heavy bleeding, black stools, fainting, chest pain, vomiting that will not stop, or pain unlike baseline after activity.', 'Bring activity logs to GI visits so clinicians see context.', 'Celebrate restarted weeks after setbacks; that skill predicts long term fitness.', 'Education supports shared decisions with gastroenterology and physical therapy teams.']), ('Shoes, surfaces, and joint kindness', ['Rotate two pair running shoes to reduce repetitive stress.', 'Soft trails may beat concrete for jostled guts when ankles allow.', 'Replace shoes on mileage schedules even if they look fine.', 'Physical therapy gait tweaks help chronic ankle sprains common in IBD fatigue eras.']), ('Group runs and running clubs', ['Clubs vary in bathroom culture; scout routes with leaders privately.', 'It is OK to run shorter loops while group continues.', 'Night runs need reflective gear and safer neighborhoods.', 'Dog leashes on shared paths cause trip hazards; choose less crowded times.']), ('Music, podcasts, and dissociation', ['Distraction audio helps some runners manage urgency anxiety.', 'Keep volume low enough to hear traffic if road running.', 'Podcasts about IBD community can motivate or trigger; choose mindfully.', 'Running meditation apps exist for breath pacing.']), ('Post run recovery nutrition', ['Small tolerated carb protein combos help some within thirty minutes after runs.', 'Chocolate milk is classic yet lactose may fail; use lactose free versions if needed.', 'Rehydrate before heavy meals to reduce cramping.', 'Log post run stools separately from pre run meals.']), ('Sleep and early morning runs', ['Sleep debt raises injury and flare perception; skip dawn runs after insomnia nights.', 'Evening runs may collide with dinner tolerance experiments; separate variables.', 'Track sleep hours alongside mileage in IBDPal notes.', 'Naps after long runs are valid recovery, not laziness.']), ('Returning after colectomy or ostomy', ['Surgeons often clear walking before jogging; follow staged return handouts.', 'Core strength protects fresh incisions; avoid sprinting until cleared.', 'Ostomy leaks during bounce test runs at home before public loops.', 'Support groups share belt brands that stay put during miles.']), ('Weather related indoor backups', ['Mall walking hours, gym treadmills, and indoor tracks hedge storms.', 'Mask policies vary; choose venues with accessible restrooms.', 'Indoor air quality matters for asthma overlap.', 'Backup plans prevent all or nothing fitness thinking.']), ('Setting kind goals for six months', ['Pick a maximum weekly mileage ceiling with GI input, not fantasy race posters.', 'Register for events with refund policies if health shifts.', 'Celebrate month long consistency over single fast splits.', 'Revisit goals after infusion changes or steroid tapers.']), ('Warm up and cool down routines', ['Five minute walks before jogging reduce side stitch complaints for some IBD runners.', 'Gentle leg swings and hip circles help stiff sacroiliac joints.', 'Cool down walks flush lactate without sudden bathroom desperation if route planned.', 'Stretch calves after runs when Achilles tightness appears from gait changes.']), ('Reflective gear and safety', ['Vests and blinkers matter on dawn dusk routes near traffic.', 'ID bracelets listing IBD and meds help EMS if accident occurs.', 'Run against traffic on roads without sidewalks when legal locally.', 'Share live location with trusted contact during trail runs.']), ('Treadmill interval templates', ['One minute jog plus two minute walk repeated twenty minutes builds base without heroics.', 'Incline one percent mimics outdoor air resistance slightly.', 'Stop belt if cramp or urgency spikes; resume walk only when calm.', 'Gym locker rooms vary cleanliness; flip flops protect feet.']), ('Cross training on low energy weeks', ['Stationary bike or elliptical reduces impact when ankles protest.', 'Pool walking helps some; chlorine and urgency vary individually.', 'Yoga links remain valuable on rest days between jog days.', 'Strength training twice weekly supports tendons stressed by running form.']), ('Race day logistics checklist', ['Scope portajohn lines before corral entry; know mile markers with facilities on course map.', 'Safety pin bib without stoma puncture; use belt alternatives if needed.', 'Pre race dinner should be boring tolerated foods, not expo free samples.', 'Have DNS plan without self insult if flare hits race morning.']), ('Tracking metrics kindly', ['Log distance, urgency rating zero to ten, and sleep hours weekly not obsessively daily.', 'Celebrate month totals not only personal records.', 'Stop smartwatch shame notifications if they ignore medical rest weeks.', 'Share trends with GI annually, not every slow mile.']), ('Biologic travel and running camps', ['Running camps away from home need refrigerated biologic plans separate from workout plans.', 'Know nearest hospital on camp map if abdominal pain spikes during activity week.', 'Coach waiver forms should list emergency contacts and allergy meds.', 'Do not skip biologic doses to avoid missing camp; coordinate with infusion center.']), ('Foot care and blister prevention', ['Moisture wicking socks reduce blisters when urgency forces sudden stops.', 'Trim toenails before long runs to avoid black nails on downhills.', 'Treat hot spots early with tape before they bleed into shoes.', 'Alternate shoes after rain runs so insoles dry fully.']), ('Running with service or support dogs', ['Rules for animals on trails vary; service dog handlers plan bathroom routes for both.', 'Hydration packs for dogs differ from human IBD hydration plans.', 'Notify race directors about service animals when registering.', 'Clean up responsibly; bag dispensers help communities stay welcoming.']), ('Post flare return micro plan', ['Week one walk only; week two jog thirty seconds every five minutes walking.', 'Stop if nocturnal stools return; reset without guilt.', 'GI clearance after hospitalization before any impact.', 'Document return plan in portal so clinicians approve milestones.']), ('Closing planning notes for your next clinic visit', ['Print or bookmark the sections that matched your week, cross out what did not, and bring one page of questions instead of relying on memory in a rushed appointment.', 'Ask for written flare and remission targets so home experiments stay aligned with scope results, calprotectin trends, and the medicine plan you already follow.', 'If a paragraph felt confusing, note the heading in your portal message so clinicians know exactly where you need clearer guidance rather than a vague request for help.', 'Small steady steps beat dramatic overhauls that collapse after three days; consistency of logging and follow up usually matters more than perfect adherence to internet lists.']), ('Rainy day treadmill etiquette', ['Wipe machines after use when GI symptoms increase bathroom urgency frequency.', 'Choose gym times when locker rooms are staffed if you feel safer.', 'Headphones help privacy on treadmills near others.', 'Cancel gym membership guilt free during postoperative months if finances tighten.', 'Ten minutes of movement on a rainy treadmill still counts as training when storms would have cancelled an outdoor jog entirely.']), ('One sentence to remember', ['A shortened jog near home bathrooms still protects fitness identity when marathon plans wait for calmer inflammation seasons.'])],
        clinic_quote='I want to jog with my IBD. Given recent flares, anemia, or surgery, what weekly mileage and intensity are reasonable, and which symptoms should stop me immediately?',
        faqs=[('Does running cause flares?', 'Exercise does not cause IBD inflammation, yet dehydration or overtraining can worsen symptoms. Treat flares medically.'), ('Are treadmills safer?', 'They offer nearby bathrooms; many beginners prefer them for anxiety relief.'), ('Can I run with an ostomy?', 'Many people do with belts and planning; ask surgery team after recent operations.'), ('Should I eat before morning runs?', 'Small tolerated carbs help some; others prefer empty stomach trials near bathrooms.')],
        related_html=related(
            ("Walking guide", "/blog/walking-for-ibd-crohns-colitis"),
            ("Yoga guide", "/blog/yoga-for-ibd-crohns-colitis"),
            ("Strength training", "/blog/strength-training-gym-ibd"),
            ("Exercise during flare", "/blog/exercise-during-ibd-flare"),
        ),
        closing=['Running can fit IBD life when routes, fluids, and flare humility are planned. Consistency beats hero days.'],
    )
